"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");
const path = require("node:path");
const { spawn } = require("node:child_process");

const ROOT = path.resolve(__dirname, "../..");
const PLAYWRIGHT_CANDIDATES = [
  "playwright",
  path.join(path.dirname(process.execPath), "..", "lib", "node_modules", "playwright"),
];

function loadPlaywright() {
  for (const candidate of PLAYWRIGHT_CANDIDATES) {
    try { return require(candidate); } catch (err) {
      if (err.code !== "MODULE_NOT_FOUND") throw err;
    }
  }
  return null;
}

function startPreview() {
  return new Promise((resolve, reject) => {
    const python = process.env.GAMETAPE_PYTHON || "python3";
    const proc = spawn(python, [path.join(ROOT, "diagnostic/preview.py"), ROOT,
      path.join(ROOT, "diagnostic/seed.json")], { stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "", stderr = "", settled = false;
    const timer = setTimeout(() => {
      if (!settled) { settled = true; proc.kill("SIGTERM"); reject(new Error(`preview startup timed out (${python})`)); }
    }, 10000);
    proc.stdout.on("data", chunk => {
      stdout += chunk;
      const lines = stdout.split("\n");
      stdout = lines.pop();
      const line = lines.find(item => item.startsWith("{"));
      if (line && !settled) {
        settled = true;
        clearTimeout(timer);
        try { resolve({ proc, port: JSON.parse(line).port }); }
        catch (err) { reject(err); }
      }
    });
    proc.stderr.on("data", chunk => { stderr += chunk; });
    proc.on("error", err => { if (!settled) reject(err); });
    proc.on("exit", code => {
      if (!settled) reject(new Error(`preview exited ${code}: ${stderr}`));
    });
  });
}

async function reviewViewport(t, width, height) {
  const playwright = loadPlaywright();
  const lookup = PLAYWRIGHT_CANDIDATES.join(", ");
  const executablePath = process.env.GAMETAPE_CHROMIUM;
  if (!playwright) {
    t.skip(`playwright unavailable; attempted ${lookup}; GAMETAPE_CHROMIUM=${executablePath || "unset"}`);
    return;
  }

  let browser;
  try {
    browser = await playwright.chromium.launch(executablePath ? { executablePath } : {});
  } catch (err) {
    t.skip(`playwright chromium launch failed (${err.message}); attempted ${lookup}; GAMETAPE_CHROMIUM=${executablePath || "unset"}`);
    return;
  }

  let preview;
  try {
    preview = await startPreview();
    const page = await browser.newPage({ viewport: { width, height } });
    const errors = [];
    page.on("console", msg => { if (msg.type() === "error") errors.push(`console: ${msg.text()}`); });
    page.on("pageerror", err => errors.push(`pageerror: ${err.message}`));
    await page.goto(`http://127.0.0.1:${preview.port}/`);
    await page.waitForSelector(".project-card:nth-child(3)");

    const search = page.locator("#project-search");
    await search.click();
    await page.keyboard.type("alp");
    await assertState(page, { value: "alp", count: "2 of 3 projects", hash: "#q=alp",
      hidden: ["beta bowl"], visible: ["alpha cup", "alpha reserve"] });

    await page.locator("#btn-project-sort").click();
    await assertState(page, { value: "alp", count: "2 of 3 projects", hash: "#q=alp",
      sort: "asc", hidden: ["beta bowl"], visible: ["alpha cup", "alpha reserve"] });
    await page.locator("#btn-project-sort").click();
    await assertState(page, { value: "alp", count: "2 of 3 projects", hash: "#q=alp",
      sort: "desc", hidden: ["beta bowl"], visible: ["alpha reserve", "alpha cup"] });

    await search.press("Escape");
    assert.deepEqual(await page.evaluate(() => ({
      value: document.querySelector("#project-search").value,
      hash: location.hash,
      visible: [...document.querySelectorAll(".project-card")].filter(card => !card.hidden).length,
      focused: document.activeElement === document.querySelector("#project-search"),
    })), { value: "", hash: "", visible: 3, focused: true });

    const layout = await page.evaluate(() => ({
      noOverflow: document.scrollingElement.scrollWidth <= document.scrollingElement.clientWidth,
      button: document.querySelector("#btn-project-sort").getBoundingClientRect().toJSON(),
      status: document.querySelector("#project-sort-status").getBoundingClientRect().toJSON(),
    }));
    assert.equal(layout.noOverflow, true);
    assert.ok(layout.button.width > 0 && layout.button.height > 0);
    assert.ok(layout.status.width > 0 && layout.status.height > 0);
    await page.keyboard.type("zzz");
    assert.deepEqual(await page.evaluate(() => ({
      noMatch: !document.querySelector("#project-search-empty").hidden,
      trueEmpty: !document.querySelector("#projects-empty").hidden,
    })), { noMatch: true, trueEmpty: false });
    assert.deepEqual(errors, []);
  } finally {
    if (preview) {
      const exited = new Promise(resolve => preview.proc.once("exit", resolve));
      preview.proc.kill("SIGTERM");
      await exited;
    }
    await browser.close();
  }
}

async function assertState(page, expected) {
  const actual = await page.evaluate(() => ({
    value: document.querySelector("#project-search").value,
    count: document.querySelector("#project-search-count").textContent,
    hash: location.hash,
    sort: document.querySelector("#projects-container").dataset.sort,
    hidden: [...document.querySelectorAll(".project-card")].filter(card => card.hidden).map(card => card.dataset.name),
    visible: [...document.querySelectorAll(".project-card")].filter(card => !card.hidden).map(card => card.dataset.name),
  }));
  for (const [key, value] of Object.entries(expected)) assert.deepEqual(actual[key], value, key);
}

test("typed-query browser review at 1280x800", t => reviewViewport(t, 1280, 800));
test("typed-query browser review at 390x844", t => reviewViewport(t, 390, 844));

